@import "tailwindcss";
@import "tw-animate-css";

@custom-variant dark (&:is(.dark *));

:root {
  /* ─── Surfaces: warm cream paper ground, crisp white cards ─── */
  --background: oklch(0.957 0.008 85);        /* #F4F1EB warm cream paper */
  --foreground: oklch(0.31 0.006 75);         /* #2A2926 warm near-black ink */

  --card: oklch(1 0 0);                         /* white card, lifts off the cream */
  --card-foreground: oklch(0.31 0.006 75);

  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.31 0.006 75);

  /* ─── Primary: near-black action pill (flat) ─── */
  --primary: oklch(0.235 0.004 75);            /* #1A1A19 warm near-black */
  --primary-foreground: oklch(0.985 0.003 90); /* warm white */

  --secondary: oklch(0.93 0.012 86);
  --secondary-foreground: oklch(0.31 0.006 75);

  --muted: oklch(0.94 0.009 86);
  --muted-foreground: oklch(0.55 0.009 80);    /* #73706A warm grey */

  --accent: oklch(0.915 0.013 86);             /* hover surface: a step darker than secondary so hovers deepen */
  --accent-foreground: oklch(0.31 0.006 75);

  --destructive: oklch(0.63 0.235 32);         /* #FF3E00 vivid orange */
  --destructive-foreground: oklch(0.99 0 0);

  --border: oklch(0.905 0.009 85);             /* #E7E2D8 warm hairline */
  --input: oklch(0.99 0.003 88);               /* near-white field on cream */
  --ring: oklch(0.4 0.006 75);                 /* warm near-black focus/selection (UI chrome stays warm; blue lives in the pops) */
  --radius: 1rem;                               /* 1rem base: generous, friendly rounding */

  --font-sans: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", Helvetica,
    Arial, sans-serif;

  /* ─── Pop palette: vivid accent hues (soft bg + deep text). ─── */
  --pop-blue: oklch(0.92 0.045 245);
  --pop-blue-foreground: oklch(0.48 0.14 252);
  --pop-green: oklch(0.92 0.06 150);
  --pop-green-foreground: oklch(0.42 0.11 152);
  --pop-orange: oklch(0.93 0.05 40);
  --pop-orange-foreground: oklch(0.52 0.18 35);
  --pop-yellow: oklch(0.95 0.06 92);
  --pop-yellow-foreground: oklch(0.5 0.1 75);
  --pop-purple: oklch(0.92 0.05 292);
  --pop-purple-foreground: oklch(0.5 0.16 288);

  --shadow-xs:
    0 0.0625rem 0.125rem oklch(0.30 0.01 75 / 0.05);

  --shadow-sm:
    0 0 0 0.0625rem oklch(0.30 0.01 75 / 0.05),
    0 0.0625rem 0.125rem oklch(0.30 0.01 75 / 0.05);

  --shadow-md:
    0 0 0 0.0625rem oklch(0.30 0.01 75 / 0.04),
    0 0.125rem 0.375rem -0.0625rem oklch(0.30 0.01 75 / 0.06),
    0 0.5rem 1.5rem -0.375rem oklch(0.30 0.01 75 / 0.08);

  --shadow-lg:
    0 0 0 0.0625rem oklch(0.30 0.01 75 / 0.035),
    0 0.375rem 1rem -0.625rem oklch(0.30 0.01 75 / 0.06),
    0 1rem 2.75rem -1.25rem oklch(0.30 0.01 75 / 0.08);

  --shadow-xl:
    0 0 0 0.0625rem oklch(0.30 0.01 75 / 0.035),
    0 0.75rem 1.75rem -0.875rem oklch(0.30 0.01 75 / 0.07),
    0 1.75rem 4rem -1.625rem oklch(0.30 0.01 75 / 0.1);

  /* Aliases used directly by component class strings ([box-shadow:var(--shadow-s)] etc). */
  --shadow-s: var(--shadow-sm);
  --shadow-m: var(--shadow-md);
  --shadow-l: var(--shadow-lg);

  /* Inset/recessed: inputs sit gently inset, a faint warm hairline, never harsh. */
  --shadow-inset:
    inset 0 0 0 0.0625rem oklch(0.30 0.01 75 / 0.04),
    inset 0 0.0625rem 0.0625rem oklch(0.30 0.01 75 / 0.03);

  /* Default raised control (cream pill / tab): flat with a hairline + tiny lift. */
  --shadow-button:
    0 0 0 0.0625rem oklch(0.30 0.01 75 / 0.05),
    0 0.0625rem 0.0625rem oklch(0.30 0.01 75 / 0.04);

  --shadow-button-hover:
    0 0 0 0.0625rem oklch(0.30 0.01 75 / 0.06),
    0 0.125rem 0.375rem -0.0625rem oklch(0.30 0.01 75 / 0.08);

  --shadow-primary:
    0 0.0625rem 0.125rem oklch(0 0 0 / 0.12);

  --shadow-primary-hover:
    0 0.125rem 0.375rem -0.0625rem oklch(0 0 0 / 0.18);

  /* ─── Chart palette: the vivid pops. ─── */
  --chart-1: oklch(0.64 0.17 248);             /* blue */
  --chart-2: oklch(0.74 0.2 150);              /* green */
  --chart-3: oklch(0.66 0.21 38);              /* orange */
  --chart-4: oklch(0.6 0.19 288);              /* purple */
  --chart-5: oklch(0.83 0.16 88);              /* yellow */

  /* --- Motion (standard profile) ---
     Bare transition-* and ease-* classes read these; durations are
     duration-fast, duration-base and duration-slow once installed. */
  --transition-duration-fast: 150ms;
  --transition-duration-base: 200ms;
  --transition-duration-slow: 280ms;
  --ease-out: cubic-bezier(0.165, 0.84, 0.44, 1);
  --ease-in-out: cubic-bezier(0.645, 0.045, 0.355, 1);
  --ease-in: cubic-bezier(0.55, 0.055, 0.675, 0.19);
  --default-transition-duration: var(--transition-duration-fast);
  --default-transition-timing-function: var(--ease-out);

  /* AI parts: the label that marks what a model wrote. */
  --ai-label: var(--muted);
  --ai-label-foreground: var(--foreground);
}

/* Registers duration-fast, duration-base and duration-slow, which the
   components use. `reference` writes no variable that points at itself. */
@theme inline reference {
  --transition-duration-fast: var(--transition-duration-fast);
  --transition-duration-base: var(--transition-duration-base);
  --transition-duration-slow: var(--transition-duration-slow);
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);

  --color-pop-blue: var(--pop-blue);
  --color-pop-blue-foreground: var(--pop-blue-foreground);
  --color-pop-green: var(--pop-green);
  --color-pop-green-foreground: var(--pop-green-foreground);
  --color-pop-orange: var(--pop-orange);
  --color-pop-orange-foreground: var(--pop-orange-foreground);
  --color-pop-yellow: var(--pop-yellow);
  --color-pop-yellow-foreground: var(--pop-yellow-foreground);
  --color-pop-purple: var(--pop-purple);
  --color-pop-purple-foreground: var(--pop-purple-foreground);

  --font-sans: var(--font-sans);

  --radius-sm: calc(var(--radius) - 0.5rem);       /* 0.5rem  small controls */
  --radius-md: calc(var(--radius) - 0.25rem);       /* 0.75rem inputs / chips */
  --radius-lg: var(--radius);                    /* 1rem buttons-as-square / fields */
  --radius-xl: calc(var(--radius) + 0.375rem);        /* 1.375rem small cards */
  --radius-2xl: calc(var(--radius) + 0.75rem);      /* 1.75rem cards (big squircle) */
  --radius-3xl: calc(var(--radius) + 1.5rem);      /* 2.5rem hero squircle */

  --shadow-s: var(--shadow-s);
  --shadow-m: var(--shadow-m);
  --shadow-l: var(--shadow-l);
  --shadow-inset: var(--shadow-inset);
  --shadow-button: var(--shadow-button);
  --shadow-button-hover: var(--shadow-button-hover);
  --shadow-primary: var(--shadow-primary);
  --shadow-primary-hover: var(--shadow-primary-hover);
  --color-chart-1: var(--chart-1);
  --color-chart-2: var(--chart-2);
  --color-chart-3: var(--chart-3);
  --color-chart-4: var(--chart-4);
  --color-chart-5: var(--chart-5);
}

@layer base {
  * {
    @apply border-border outline-ring/50;
  }
  body {
    @apply bg-background text-foreground antialiased;
    font-family: var(--font-sans);
  }

  ::selection {
    background-color: var(--primary);
    color: var(--primary-foreground);
  }
  /* stylelint-disable-next-line selector-no-vendor-prefix */
  ::-moz-selection {
    background-color: var(--primary);
    color: var(--primary-foreground);
  }

  textarea {
    resize: vertical;
  }
  @supports (field-sizing: content) {
    textarea {
      field-sizing: content;
      max-height: 20lh;
      overflow-y: auto;
    }
  }

  /* Reserve the scrollbar gutter so the page keeps its width whenever the
     scrollbar comes and goes: content loading in, moving between a short
     and a tall page, or a scroll lock that just hides overflow. */
  html {
    scrollbar-gutter: stable;
  }
  @supports (scrollbar-gutter: stable) {
    html body[data-scroll-locked] {
      /* Radix's scroll lock re-adds the scrollbar width as body margin. The
         stable gutter already reserves it, so without this the two stack and
         opening a dialog shifts the page the other way. */
      margin-right: 0 !important;
    }
  }
}

@layer utilities {
  /* Show an invalid field on the field itself, not only in the message under
     it. Declared after Tailwind's utilities, so it wins over the field's own
     border and focus-ring classes. */
  [aria-invalid="true"]:is(input, textarea, select, [role="combobox"], [role="checkbox"], [role="radio"]),
  [role="radiogroup"][aria-invalid="true"] [role="radio"] {
    border-color: var(--destructive);
  }
  [aria-invalid="true"]:is(input, textarea, select, [role="combobox"], [role="checkbox"], [role="radio"]):focus-visible,
  [role="radiogroup"][aria-invalid="true"] [role="radio"]:focus-visible {
    border-color: var(--destructive);
    --tw-ring-color: color-mix(in oklch, var(--destructive) 35%, transparent);
  }

  /* Shake a field once when it turns invalid. */
  @keyframes deny-shake {
    25% { translate: -0.09375rem; }
    50% { translate: 0.109375rem; }
    75% { translate: -0.109375rem; }
  }
  @media (prefers-reduced-motion: no-preference) {
    [aria-invalid="true"]:is(input, textarea, select, [role="combobox"], [role="checkbox"], [role="radio"]),
    [role="radiogroup"][aria-invalid="true"] [role="radio"],
    [data-input-otp-container]:has([aria-invalid="true"]) {
      animation: deny-shake 250ms linear;
    }
  }
}

:root {
  --layout-density: spacious;
  --layout-density-source: design-system;
  --layout-sidebar: calc(var(--spacing, 0.25rem) * 62);
  --layout-inset: calc(var(--spacing, 0.25rem) * 10);
  --layout-section-gap: calc(var(--spacing, 0.25rem) * 12);
  --layout-column-gap: calc(var(--spacing, 0.25rem) * 4);
  --layout-card-padding: calc(var(--spacing, 0.25rem) * 6);
}

